  'Pour la diaspora, les conditions varient selon la banque — se renseigner directement auprès de l etablissement':'ⴱⵓⵓⵔ ⵍⴰ ⴷⵉⴰⵙⴱⵓⵔⴰ, ⵍⴻⵙ ⵙⵓⵏⴷⵉⵜⵉⵓⵏⵙ ⴼⴰⵔⵉⴻⵏⵜ ⵙⴻⵍⵓⵏ ⵍⴰ ⴱⴰⵏⵇⵓⴻ  ⵙⴻ ⵔⴻⵏⵙⴻⵉⴳⵏⴻⵔ ⴷⵉⵔⴻⵙⵜⴻⵎⴻⵏⵜ ⴰⵓⴱⵔⴻⵙ ⴷⴻ ⵍ ⴻⵜⴰⴱⵍⵉⵙⵙⴻⵎⴻⵏⵜ',
