  'كل مهني مُثبتٌ إدانته بانتحال لقب أو احتيال يتعرض للملاحقة القضائية وفق القانون الجزائري و/أو الفرنسي. تحتفظ DZ Diaspora بحق إبلاغ السلطات المختصة عن أي سلوك احتيالي.':'/ .  ⴷⵣ ⴷⵉⴰⵙⴱⵓⵔⴰ        .',
  'يحق لـ DZ Diaspora فسخ العقد فوراً دون استرداد في حال التصريح الكاذب أو السلوك المخالف للأخلاق أو شكوى موثوقة. يمكن للمهني الفسخ مع إشعار 30 يوماً دون استرداد للفترة الجارية.':'ⴷⵣ ⴷⵉⴰⵙⴱⵓⵔⴰ                .      30     .',
  'يلتزم المهني بتقديم معلومات دقيقة، الرد على العملاء خلال 48 ساعة، احترام السرية المهنية وأخلاقيات المهنة، وإبلاغ DZ Diaspora بأي تغيير.':'48        ⴷⵣ ⴷⵉⴰⵙⴱⵓⵔⴰ  .',
