  '— certains terrains vendus comme "a batir" sont en realite classes zone agricole ou forestiere, ou issus d un morcellement illegal':'ⵙⴻⵔⵜⴰⵉⵏⵙ ⵜⴻⵔⵔⴰⵉⵏⵙ ⴼⴻⵏⴷⵓⵙ ⵙⵓⵎⵎⴻ "ⴰ ⴱⴰⵜⵉⵔ" ⵙⵓⵏⵜ ⴻⵏ ⵔⴻⴰⵍⵉⵜⴻ ⵙⵍⴰⵙⵙⴻⵙ ⵣⵓⵏⴻ ⴰⴳⵔⵉⵙⵓⵍⴻ ⵓⵓ ⴼⵓⵔⴻⵙⵜⵉⴻⵔⴻ, ⵓⵓ ⵉⵙⵙⵓⵙ ⴷ ⵓⵏ ⵎⵓⵔⵙⴻⵍⵍⴻⵎⴻⵏⵜ ⵉⵍⵍⴻⴳⴰⵍ',
  '— certains vendeurs majorent le prix pour les acheteurs residant a l etranger. Renseignez-vous sur les prix reels du marche local avant de negocier':'ⵙⴻⵔⵜⴰⵉⵏⵙ ⴼⴻⵏⴷⴻⵓⵔⵙ ⵎⴰⵊⵓⵔⴻⵏⵜ ⵍⴻ ⴱⵔⵉⵅ ⴱⵓⵓⵔ ⵍⴻⵙ ⴰⵙⵀⴻⵜⴻⵓⵔⵙ ⵔⴻⵙⵉⴷⴰⵏⵜ ⴰ ⵍ ⴻⵜⵔⴰⵏⴳⴻⵔ. ⵔⴻⵏⵙⴻⵉⴳⵏⴻⵣ-ⴼⵓⵓⵙ ⵙⵓⵔ ⵍⴻⵙ ⴱⵔⵉⵅ ⵔⴻⴻⵍⵙ ⴷⵓ ⵎⴰⵔⵙⵀⴻ ⵍⵓⵙⴰⵍ ⴰⴼⴰⵏⵜ ⴷⴻ ⵏⴻⴳⵓⵙⵉⴻⵔ',
