const _orig = new Map();
var _kabActif = false;

function normaliserTexte(t) {
  return t.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\u2018\u2019]/g, "'").replace(/[\u2014\u2013]/g, '-').trim();
}

function traduireElement(el) {
  if (el.children.length === 0) {
    var t = el.textContent.trim();
    var tNorm = normaliserTexte(t);
    var trad = TRAD_KAB_SITE[t] || TRAD_KAB_SITE[tNorm];
    if (trad && el.textContent !== trad) {
      if (!_orig.has(el)) _orig.set(el, t);
      el.textContent = trad;
    }
  }
}

var _observer = new MutationObserver(function() {
  if (_kabActif) {
    setTimeout(function() {
      document.querySelectorAll('a,button,h1,h2,h3,h4,h5,li,span,p,td,th,label,div').forEach(traduireElement);
    }, 300);
  }
});

function appliquerTamazight() {
  _kabActif = true;
  _observer.observe(document.body, {childList: true, subtree: true});
  document.querySelectorAll('a,button,h1,h2,h3,h4,h5,li,span,p,td,th,label,div').forEach(traduireElement);
}

function restaurer() {
  _kabActif = false;
  _observer.disconnect();
  _orig.forEach(function(t, el) { el.textContent = t; });
  _orig.clear();
}

function effacerCookiesGT() {
  var d = window.location.hostname;
  var e = 'expires=Thu, 01 Jan 1970 00:00:00 UTC';
  document.cookie = 'googtrans=; ' + e + '; path=/';
  document.cookie = 'googtrans=; ' + e + '; path=/; domain=' + d;
  document.cookie = 'googtrans=; ' + e + '; path=/; domain=.' + d;
}

function changerLangueSite(lang) {
  document.querySelectorAll('.lang-btn').forEach(function(b) { b.classList.remove('active'); });
  var btn = document.querySelector('.lang-btn[data-lang="' + lang + '"]');
  if (btn) btn.classList.add('active');
  document.documentElement.dir = (lang === 'ar') ? 'rtl' : 'ltr';
  if (lang === 'kab') {
    effacerCookiesGT();
    restaurer();
    setTimeout(appliquerTamazight, 200);
    return;
  }
  restaurer();
  effacerCookiesGT();
  if (lang === 'fr') { window.location.reload(); return; }
  var code = (lang === 'zh') ? 'zh-CN' : lang;
  setTimeout(function() {
    document.cookie = 'googtrans=/fr/' + code + '; path=/';
    document.cookie = 'googtrans=/fr/' + code + '; path=/; domain=.' + window.location.hostname;
    window.location.reload();
  }, 100);
}

window._gtDone = false;
function googleTranslateElementInit() {
  if (window._gtDone) return;
  window._gtDone = true;
  try {
    new google.translate.TranslateElement(
      {pageLanguage: 'fr', includedLanguages: 'fr,en,zh-CN,ar', autoDisplay: false},
      'google_translate_element'
    );
  } catch(e) {}
}

document.addEventListener('DOMContentLoaded', function() {
  document.querySelectorAll('.lang-btn').forEach(function(b) { b.classList.add('notranslate'); });
  var div = document.createElement('div');
  div.id = 'google_translate_element';
  div.style.display = 'none';
  document.body.appendChild(div);
  var gt = document.createElement('script');
  gt.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
  gt.onerror = function() {};
  document.body.appendChild(gt);
});
